// Iron Banners — conquest: the Great Heathen Army in England, 865–878.
'use strict';

// ---------- Viking Age units (also used by the battles in scenarios4.js)
unit('vk_warband', { name: 'Viking Warband', cls: 'inf', era: 2, atk: 8, def: 7, mor: 70, tags: ['shieldwall'], br: 2.4, hidden: true, note: 'A ship\'s crew or two fighting as one: spears, axes, round linden shields, a few mail shirts and helmets. They rode to battle and fought on foot in a shield wall.' });
unit('vk_hird',    { name: 'Jarl\'s Hird', cls: 'inf', era: 2, atk: 10, def: 9, mor: 85, tags: ['shieldwall', 'discipline'], br: 2.8, hidden: true, note: 'The sworn household warriors of a king or jarl, the best-armed men in the host: mail, helmets, swords and broad axes.' });
unit('vk_raider',  { name: 'Mounted Raiders', cls: 'inf', era: 2, atk: 7, def: 5, mor: 65, tags: ['feint'], br: 2.3, hidden: true, note: 'Warriors on seized English horses. They rode fast and far, then dismounted to fight — able to break off, slip away and strike somewhere else.' });
unit('vk_archer',  { name: 'Viking Bowmen', cls: 'missile', era: 2, atk: 5, def: 3, mor: 55, br: 1.6, hidden: true, note: 'Self bows of yew or elm. Every crew had a few archers to open the fight before the shield walls met.' });
unit('vk_berserk', { name: 'Berserkers', cls: 'inf', era: 2, atk: 12, def: 5, mor: 90, tags: ['shock', 'fear', 'unstable'], br: 2.6, hidden: true, note: 'Skaldic poems and the later sagas tell of berserkir and úlfheðnar, warriors in bear and wolf skins who fought in a frenzy. How far they were real fighting bands, and not poetry, is uncertain.' });
unit('vk_nomail',  { name: 'Norsemen without Mail', cls: 'inf', era: 2, atk: 8, def: 4, mor: 70, tags: ['shieldwall'], br: 2.2, hidden: true, note: 'Norwegian warriors caught on a hot day with their mail shirts left behind at the ships.' });
unit('sax_thegn',  { name: 'Saxon Thegns', cls: 'inf', era: 2, atk: 9, def: 9, mor: 75, tags: ['shieldwall'], br: 2.6, hidden: true, note: 'Landholders who owed the king military service, with helmets, mail or leather coats, spears and swords. The backbone of every English shield wall.' });
unit('sax_gesith', { name: 'Royal Household', cls: 'inf', era: 2, atk: 10, def: 10, mor: 85, tags: ['shieldwall', 'discipline'], br: 2.8, hidden: true, note: 'The king\'s own companions (gesithas), fed in his hall and sworn to die with him.' });

